arguments.file_text:
#:property AllowUnsafeBlocks=true

Span<nint> nints = stackalloc nint[4];
for (int i = 0; i < nints.Length; i++)
    nints[i] = (nint)(i * 10);

Console.WriteLine($"Span<nint> length: {nints.Length}, element size: {nint.Size} bytes");
for (int i = 0; i < nints.Length; i++)
    Console.WriteLine($"  [{i}] = {nints[i]}");

Span<nuint> nuints = stackalloc nuint[3];
nuints[0] = 100;
nuints[1] = 200;
nuints[2] = 300;

Console.WriteLine($"\nSpan<nuint> length: {nuints.Length}, element size: {nuint.Size} bytes");
for (int i = 0; i < nuints.Length; i++)
    Console.WriteLine($"  [{i}] = {nuints[i]}");

